import {useMemo,useState,type ReactNode} from 'react';
import {ArrowRight,ArrowUpRight,Atom,BookOpen,Check,ChevronDown,ChevronRight,Compass,Crown,Download,Flag,FlaskConical,Globe2,Info,Leaf,Minus,Orbit,Plus,Radio,Search,Shield,Rocket as Ship,Sparkles,Swords,Target,Trash2,Users,Volume2,Zap} from 'lucide-react';
import type {BuildOrder,Command,Empire,Fleet,GameState,Planet,ShipDesign,Species} from '../../../packages/sim/src/types';
import {aiOrders,canMove,canQueue,cost,planetById,purchasePrice,relation,score} from '../../../packages/sim/src/engine';
