import {aptitude,autoDesign,availableResearch,BUILDINGS,capacity,CIVIL,colonies,designStats,drive,fleetSpeed,FIELDS,FOCUSES,GOVERNMENTS,habitability,has,HULLS,output,PROJECTS,researchCost,speciesFor,STRATEGIES,supply,TECHS,WEAPONS} from '../../../packages/sim/src/rules';
import {distance} from '../../../packages/sim/src/math';
